const fs = require("fs");
const p = "/home/debian19y/.claude/settings.json";
const raw = fs.readFileSync(p, "utf8");
const cfg = JSON.parse(raw);
const stamp = new Date().toISOString().replace(/[-:T.Z]/g, "").slice(0, 14);
const backup = `${p}.bak.${stamp}-before-sonnet5-1m`;
fs.copyFileSync(p, backup);
cfg.env = cfg.env || {};
cfg.model = "sonnet[1m]";
cfg.env.ANTHROPIC_MODEL = "claude-sonnet-5[1m]";
cfg.env.ANTHROPIC_DEFAULT_SONNET_MODEL = "claude-sonnet-5[1m]";
cfg.env.CLAUDE_CODE_SUBAGENT_MODEL = "claude-sonnet-5[1m]";
delete cfg.env.CLAUDE_CODE_DISABLE_1M_CONTEXT;
delete cfg.env.CLAUDE_CODE_DISABLE_EXPERIMENTAL_BETAS;
fs.writeFileSync(p, JSON.stringify(cfg, null, 2) + "\n");
console.log(`updated ${p}`);
console.log(`backup ${backup}`);
'
